import hashlib
from pathlib import Path

from langchain_core.tools import tool

_EXTS = {".jpg", ".jpeg", ".png", ".heic", ".mp4", ".mov"}


def _sha1(path):
    h = hashlib.sha1()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


@tool
def find_duplicate_photos(library_path: str, min_size_kb: int = 0) -> dict:
    root = Path(library_path)
    if not root.exists():
        return {"error": f"path not found: {library_path}"}
    if not root.is_dir():
        return {"error": "library_path must be a directory"}
    if min_size_kb < 0:
        return {"error": "min_size_kb must be >= 0"}

    seen = {}
    for p in root.rglob("*"):
        if not p.is_file() or p.suffix.lower() not in _EXTS:
            continue
        if p.stat().st_size < min_size_kb * 1024:
            continue
        seen.setdefault(_sha1(p), []).append(str(p))

    groups = [v for v in seen.values() if len(v) > 1]
    return {"group_count": len(groups), "groups": groups}

import os
import shutil
import sqlite3

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("media-library")

DB_PATH = os.environ.get("MEDIA_DB", "/var/lib/medialib/library.db")


@mcp.tool()
def move_album_to_archive(album_name: str, archive_dir: str) -> dict:
    if not album_name.strip():
        return {"error": "album_name is required"}
    if not archive_dir.strip():
        return {"error": "archive_dir is required"}
    if os.path.exists(archive_dir) and not os.path.isdir(archive_dir):
        return {"error": "archive_dir exists and is not a directory"}

    conn = sqlite3.connect(DB_PATH)
    album = conn.execute("SELECT id FROM albums WHERE name = ?", (album_name,)).fetchone()
    if album is None:
        conn.close()
        return {"error": f"album not found: {album_name}"}

    rows = conn.execute(
        "SELECT m.id, m.path FROM media m JOIN album_media am ON am.media_id = m.id WHERE am.album_id = ?",
        (album[0],),
    ).fetchall()
    if not rows:
        conn.close()
        return {"error": "album has no media"}

    target = os.path.join(archive_dir, album_name)
    os.makedirs(target, exist_ok=True)
    moved = []
    for media_id, path in rows:
        if not os.path.isfile(path):
            continue
        new_path = os.path.join(target, os.path.basename(path))
        if os.path.exists(new_path):
            continue
        shutil.move(path, new_path)
        conn.execute("UPDATE media SET path = ? WHERE id = ?", (new_path, media_id))
        moved.append(new_path)

    conn.commit()
    conn.close()
    return {"album": album_name, "moved": moved, "remaining": len(rows) - len(moved)}
